import { DEV_SERVER_ENDPOINTS, HTTP_CONTENT_TYPES, HTTP_OK, HTTP_SERVER_ERROR, HTTP_UNAVAILABLE, serverLogger, } from "../../utils/index.js";
import { clearConfigCache } from "../../config/index.js";
import { ErrorOverlay, parseErrorLocation } from "./error-overlay/index.js";
import { createResponseBuilder } from "../../security/index.js";
import { resetApiHandler } from "../handlers/request/api/pages-api-handler.js";
import { clearLayoutDiscoveryCache } from "../../rendering/layouts/index.js";
import { clearRendererCacheForProject } from "../../rendering/renderer.js";
import { getErrorCollector } from "../../observability/error-collector.js";
import { getLogBuffer } from "../../observability/log-buffer.js";
import { invalidateRSCHandlersForProject } from "../services/rsc/endpoints/handler-registry.js";
import { invalidateProjectCandidateScans } from "../handlers/dev/styles-candidate-scanner.js";
import { invalidateProjectCssImportScans } from "../handlers/dev/styles-css-import-scanner.js";
import { invalidateProjectCandidateManifests } from "../../rendering/orchestrator/css-candidate-manifest.js";
const logger = serverLogger.component("dev");
export class RequestHandler {
    projectDir;
    adapter;
    isReady;
    config;
    defaultProjectSlug;
    defaultProjectId;
    localProjects;
    runtimeHandler;
    constructor(projectDir, adapter, isReady, config, defaultProjectSlug, defaultProjectId, localProjects) {
        this.projectDir = projectDir;
        this.adapter = adapter;
        this.isReady = isReady;
        this.config = config;
        this.defaultProjectSlug = defaultProjectSlug;
        this.defaultProjectId = defaultProjectId;
        this.localProjects = localProjects;
    }
    async handleRequest(req) {
        const url = new URL(req.url);
        const start = performance.now();
        logger.debug(`Request: ${req.method} ${url.pathname}`);
        const healthResponse = this.handleHealthCheck(url.pathname);
        if (healthResponse)
            return healthResponse;
        void this.incrementRequestMetrics();
        try {
            const devResponse = this.handleDevEndpoint(req, url.pathname);
            if (devResponse) {
                this.logRequest(req.method, url.pathname, devResponse.status, start);
                return devResponse;
            }
            const response = await this.handleApplicationRequest(req);
            this.logRequest(req.method, url.pathname, response.status, start);
            return response;
        }
        catch (error) {
            this.logRequest(req.method, url.pathname, HTTP_SERVER_ERROR, start);
            return this.handleServerError(error);
        }
    }
    logRequest(method, pathname, status, start) {
        if (pathname.startsWith("/_dev/") || pathname.startsWith("/_veryfront/"))
            return;
        const duration = Math.round(performance.now() - start);
        getLogBuffer().info(`${method} ${pathname} → ${status} (${duration}ms)`, "http", {
            method,
            path: pathname,
            status,
            duration,
        });
    }
    handleHealthCheck(pathname) {
        if (pathname === "/healthz") {
            return new Response("ok", {
                status: HTTP_OK,
                headers: { "content-type": "text/plain" },
            });
        }
        if (pathname !== "/readyz")
            return null;
        const ready = this.isReady();
        return new Response(ready ? "ready" : "not-ready", {
            status: ready ? HTTP_OK : HTTP_UNAVAILABLE,
            headers: { "content-type": "text/plain" },
        });
    }
    async incrementRequestMetrics() {
        try {
            const { metrics } = await import("../../observability/simple-metrics/index.js");
            void metrics.incRequest();
        }
        catch (error) {
            logger.debug("[dev] metrics.incRequest failed", error);
        }
    }
    handleDevEndpoint(req, pathname) {
        const normalized = this.normalizeDevEndpoint(pathname);
        if (!normalized)
            return null;
        const isHeadRequest = req.method.toUpperCase() === "HEAD";
        const builder = createResponseBuilder({ isDev: true }).withHeaders({
            "cache-control": "no-cache",
            "X-Content-Type-Options": "nosniff",
        });
        switch (normalized) {
            case DEV_SERVER_ENDPOINTS.ERROR_OVERLAY: {
                const overlay = isHeadRequest ? null : ErrorOverlay.getRuntime();
                return builder.withContentType(HTTP_CONTENT_TYPES.JS, overlay, HTTP_OK);
            }
            default:
                return null;
        }
    }
    normalizeDevEndpoint(pathname) {
        const validEndpoints = new Set([
            DEV_SERVER_ENDPOINTS.ERROR_OVERLAY,
        ]);
        if (validEndpoints.has(pathname))
            return pathname;
        if (!pathname.startsWith("/__veryfront/"))
            return null;
        const rewritten = pathname.replace("/__veryfront/", "/_veryfront/");
        return validEndpoints.has(rewritten) ? rewritten : null;
    }
    async handleApplicationRequest(req) {
        if (!this.runtimeHandler) {
            const { createVeryfrontHandler } = await import("../runtime-handler/index.js");
            this.runtimeHandler = createVeryfrontHandler(this.projectDir, this.adapter, {
                projectDir: this.projectDir,
                moduleServerUrl: "/_vf_modules",
                config: this.config,
                defaultProjectSlug: this.defaultProjectSlug,
                defaultProjectId: this.defaultProjectId,
                localProjects: this.localProjects,
            });
        }
        return this.runtimeHandler(req);
    }
    invalidateRuntimeHandler() {
        this.runtimeHandler = undefined;
        invalidateRSCHandlersForProject(this.projectDir, this.defaultProjectId);
        // The stylesheet route memoizes its source-tree scans, and a local project
        // resolves no content context, so those entries are scoped by the project
        // directory and `clearProjectCSSCache` (wired only for the control-plane
        // filesystem adapter) never reaches them. Without this a class or an
        // `import "./x.css"` added by the save that triggered this invalidation
        // could be missing from the next stylesheet fetch, because the reload
        // usually lands inside the scan cache's short mutable TTL. The scope is the
        // directory those entries are keyed by, so no other project is affected.
        invalidateProjectCandidateScans(this.projectDir);
        invalidateProjectCandidateManifests(this.projectDir);
        invalidateProjectCssImportScans(this.projectDir);
        resetApiHandler(this.projectDir).catch((error) => {
            logger.debug("resetApiHandler failed", error);
        });
        clearConfigCache();
        clearLayoutDiscoveryCache();
        const rendererProjectKey = this.defaultProjectId ?? this.defaultProjectSlug ?? "local";
        clearRendererCacheForProject(rendererProjectKey).catch((error) => {
            logger.debug("clearRendererCacheForProject failed", error);
        });
    }
    handleServerError(error) {
        logger.error("Server error:", error);
        const err = error;
        getErrorCollector().addRuntimeError(err.message, err.stack, { source: "request-handler" });
        const sourceFile = err.sourceFile;
        const location = sourceFile ? parseErrorLocation(err, sourceFile) : {};
        return new Response(ErrorOverlay.createHTML({
            type: "runtime",
            error: err,
            ...(sourceFile ? { file: sourceFile } : {}),
            ...location,
        }, this.defaultProjectSlug), {
            status: HTTP_SERVER_ERROR,
            headers: { "content-type": "text/html; charset=utf-8" },
        });
    }
}
